,"type":"superstar"},{"name":"Possession Catch","description":"Mapped from 2K8 skill 'Possession'.","type":"superstar"}]},{"name":"Steve Tasker","abilities":[{"name":"Route Technician","description":"Superstar: route nuance.","type":"superstar"},{"name":"Acrobat","description":"Superstar: contested catches.","type":"superstar"},{"name":"Possession Catch","description":"Superstar: reliable hands.","type":"superstar"}]},{"name":"Tony Martin","abilities":[{"name":"Deep Out Elite","description":"Mapped from 2K8 skill 'Deep Threat'.","type":"superstar"}]},{"name":"Wesley Walker","abilities":[{"name":"Juke Box","description":"Mapped from 2K8 skill 'Magic Feet'.","type":"superstar"},{"name":"Deep Out Elite","description":"Mapped from 2K8 skill 'Deep Threat'.","type":"superstar"},{"name":"Return Man","description":"Mapped from 2K8 skill 'Return Spec'.","type":"superstar"}]},{"name":"Willie Gault","abilities":[{"name":"Deep Out Elite","description":"Mapped from 2K8 skill 'Deep Threat'.","type":"superstar"},{"name":"Racetrack","description":"Mapped from 2K8 skill 'Speed Burner'.","type":"superstar"}]},{"name":"Yancey Thigpen","abilities":[{"name":"Possession Catch","description":"Mapped from 2K8 skill 'Soft Hands'.","type":"superstar"}]}]$json$::jsonb) AS x(name text, abilities jsonb)
